def average(nums):
    if not nums:
        return 0
    total = 0
    for n in nums:
        total = total + n
    return round(total / len(nums), 1)

def hours_by_person(rows):
    totals = {}
    for r in rows:
        totals[r['name']] = totals.get(r['name'], 0) + r['hours']
    return totals
